/**
 * generated by stackra gen from src/config/seo.config.ts (sitemaps) — do not edit
 * Purpose: `/sitemap.xml`: the index that lists one sitemap per source (marketing, pages,
 *          products).
 * Boundary: a non-indexable site has no sitemap; the index answers 404 there.
 * Runtime: worker
 */
import { routeContext } from "@stackra/navigation/router";
import { writeSitemapIndex } from "@stackra/seo/sitemap";
import type { Route } from "./+types/sitemap-index.route";
import { sitemapSources } from "#stackra/sitemap";
import { resolveSite } from "#src/server/resolve-site.server";

export async function loader(args: Route.LoaderArgs) {
  const site = await resolveSite(routeContext(args));
  if (!site.indexable) return new Response(null, { status: 404 });
  const body = writeSitemapIndex(
    Object.keys(sitemapSources).map((name) => `${site.origin}/sitemaps/${name}.xml`),
  );
  return new Response(body, {
    headers: {
      "Content-Type": "application/xml; charset=utf-8",
      "Cache-Control": "public, max-age=3600",
    },
  });
}
